def _check_delimiter(delimiter):
    if not isinstance(delimiter, str) or len(delimiter) != 1:
        raise ValueError("delimiter must be exactly one character")
    if delimiter == '"' or delimiter == "\n" or delimiter == "\r":
        raise ValueError("delimiter must not be \", \\n or \\r")


def parse_record(text, delimiter=","):
    """Split one delimited record into its fields. See TASK.md."""
    _check_delimiter(delimiter)
    if not isinstance(text, str):
        raise ValueError("text must be a string")

    fields = []
    i = 0
    n = len(text)
    while True:
        # Parse one field starting at i.
        if i < n and text[i] == '"':
            # Quoted field.
            i += 1  # skip opening quote
            buf = []
            closed = False
            while i < n:
                ch = text[i]
                if ch == '"':
                    # Either an escaped quote or the closing quote.
                    if i + 1 < n and text[i + 1] == '"':
                        buf.append('"')
                        i += 2
                    else:
                        # Closing quote.
                        i += 1
                        closed = True
                        break
                else:
                    buf.append(ch)
                    i += 1
            if not closed:
                raise ValueError("quoted field never closes")
            # After the closing quote must come delimiter or end of text.
            fields.append("".join(buf))
            if i == n:
                break
            nxt = text[i]
            if nxt == delimiter:
                i += 1
                # An empty field after the delimiter: handled at top of loop.
                if i == n:
                    fields.append("")
                    break
                continue
            # Anything else (including \n, \r, or another character) is invalid.
            raise ValueError("unexpected character after closing quote")
        else:
            # Unquoted field. Read until delimiter or end of text.
            buf = []
            while i < n:
                ch = text[i]
                if ch == delimiter:
                    break
                if ch == '"' or ch == "\n" or ch == "\r":
                    raise ValueError("invalid character in unquoted field")
                buf.append(ch)
                i += 1
            fields.append("".join(buf))
            if i == n:
                break
            # ch == delimiter
            i += 1
            if i == n:
                fields.append("")
                break
            continue
    return fields


def format_record(fields, delimiter=","):
    """Write fields as one delimited record. See TASK.md."""
    _check_delimiter(delimiter)
    if not isinstance(fields, (list, tuple)):
        raise ValueError("fields must be a list")
    if len(fields) < 1:
        raise ValueError("fields must hold at least one field")
    for f in fields:
        if not isinstance(f, str):
            raise ValueError("every field must be a str")

    out = []
    for f in fields:
        needs_quotes = (
            delimiter in f
            or '"' in f
            or "\n" in f
            or "\r" in f
            or (f != f.strip())  # starts or ends with a space
        )
        if needs_quotes:
            out.append('"' + f.replace('"', '""') + '"')
        else:
            out.append(f)
    return delimiter.join(out)
